def ReFormatString(S, K):
    S = S.replace('-', '').upper()
    n = len(S)
    if n <= K:
        return S
    first_part_length = n % K
    result = [S[:first_part_length]] if first_part_length else []
    for i in range(first_part_length, n, K):
        result.append(S[i:i+K])
    return '-'.join(result)
